 98	    uint128 lastEntry = totalEntries + entryCount;
 99	    ticketId = uint256(ticketCount) + 1;
100	
101	    totalEntries = lastEntry;
102	    ++ticketCount;
103	    _ticketRanges[ticketId] = TicketRange({ firstEntry: firstEntry, lastEntry: lastEntry });
104	    unsettledPot += grossAmount;
105	
106	    _safeMint(recipient, ticketId);
